from flask import Flask, request, jsonify

app = Flask(__name__)

# Mock data for demonstration purposes
data = [
    {"id": 1, "name": "Apples", "quantity": 2},
    {"id": 2, "name": "Bananas", "quantity": 3}
]

# Route to get all grocery items
@app.route('/groceries', methods=['GET'])
def get_all_gr Grocery_items():
    return jsonify({
        "status": "success",
        "groceries": data
    })

# Route to get a grocery item by id
@app.route('/groceries/<int: Grocery_ID>', methods=['GET'])
def get_one_gr Grocery_item(Grocery_ID):
    grocery = [grocery for grocery in data if grocery['id'] == Grocery_ID][0]
    return jsonify({
        "status": "success",
        "grocery": grocery
    })

# Route to create a new grocery item
@app.route('/groceries', methods=['POST'])
def create_gr Grocery_item():
    new_grocery = request.get_json()
    new_grocery['id'] = max(data['id']) + 1
    data.append(new_grocery)
    return jsonify({
        "status": "success",
        "grocery": new_grocery
    }), 201

# Route to update a grocery item by id
@app.route('/groceries/<int:Grocery_ID>', methods=['PUT'])
def update_gr Grocery_item(Grocery_ID):
    grocery = [grocery for grocery in data if grocery['id'] == Grocery_ID][0]
    new_data = request.get_json()
    for key, value in new_data.items():
        grocery[key] = value
    return jsonify({
        "status": "success",
        "grocery": grocery
    })

# Route to delete a grocery item by id
@app.route('/groceries/<int:Grocery_ID>', methods=['DELETE'])
def delete_gr Grocery_item(Grocery_ID):
    grocery = [grocery for grocery in data if grocery['id'] == Grocery_ID][0]
    grocery.pop('id')
    return jsonify({
        "status": "success",
        "message": "Grocery deleted successfully!"
    })

if __name__ == '__main__':
    app.run()

