});

export class GroceriesRepository {
  async list(): Promise<Grocery[]> {
    return connection('groceries').select();
  }

  async get(id: number): Promise<Grocery| null> {
    return connection('groceries')
      .where({ id })
      .first();
  }

  async create(grocery: Grocery): Promise<Grocery> {
    return connection('groceries')
      .insert(grocery)
      .returning('*');
  }

  async update(id: number, grocery: Partial<Grocery>): Promise<Grocery| null> {
    return connection('groceries')
      .where({ id })
      .update(grocery)
      .returning('*');
  }

  async delete(id: number): Promise<void> {
    return connection('groceries')
      .where({ id })
      .delete();
  }
}

